318	static int starcos_select_mf(sc_card_t * card) {
319		sc_apdu_t apdu;
320		const u8 mf_buf[2] = {0x3f, 0x00};
321	
322		sc_format_apdu(card, &apdu, SC_APDU_CASE_3_SHORT, 0xA4, 0x00, 0x0C);
323		apdu.le = 0;
324		apdu.lc = 2;
325		apdu.data    = mf_buf;
326		apdu.datalen = 2;
327		apdu.resplen = 0;
328	
329		return sc_transmit_apdu(card, &apdu);
330	}
