469	static int starcos_finish(sc_card_t *card)
470	{
471		if (card->drv_data)
472			free((starcos_ex_data *)card->drv_data);
473		return 0;
474	}
475	
476	static int process_fci(sc_context_t *ctx, sc_file_t *file,
477			       const u8 *buf, size_t buflen)
478	{
479		/* NOTE: According to the Starcos S 2.1 manual it's possible
480		 *       that a SELECT DF returns as a FCI arbitrary data which
481		 *       is stored in a object file (in the corresponding DF)
482		 *       with the tag 0x6f.
483		 */
484	
485		size_t taglen, len = buflen;
486		const u8 *tag = NULL, *p;
487	
488		sc_log(ctx,  "processing FCI bytes\n");
489	
490		if (buflen < 2)
491			return SC_ERROR_INTERNAL;
492		if (buf[0] != 0x6f)
493			return SC_ERROR_INVALID_DATA;
494		len = (size_t)buf[1];
495		if (buflen - 2 < len)
496			return SC_ERROR_INVALID_DATA;
497		p = buf + 2;
498	
499		/* defaults */
500		file->type = SC_FILE_TYPE_WORKING_EF;
501		file->ef_structure = SC_FILE_EF_UNKNOWN;
502		file->shareable = 0;
503		file->record_length = 0;
504		file->size = 0;
505	
506		tag = sc_asn1_find_tag(ctx, p, len, 0x80, &taglen);
507		if (tag != NULL && taglen >= 2) {
508			int bytes = (tag[0] << 8) + tag[1];
509			sc_log(ctx,
510				"  bytes in file: %d\n", bytes);
511			file->size = bytes;
512		}
513	
514		tag = sc_asn1_find_tag(ctx, p, len, 0x82, &taglen);
515		if (tag != NULL) {
516			const char *type = "unknown";
517			const char *structure = "unknown";
518	
519			if (taglen == 1 && tag[0] == 0x01) {
520				/* transparent EF */
521				type = "working EF";
522				structure = "transparent";
523				file->type = SC_FILE_TYPE_WORKING_EF;
524				file->ef_structure = SC_FILE_EF_TRANSPARENT;
525			} else if (taglen == 1 && tag[0] == 0x11) {
526				/* object EF */
527				type = "working EF";
528				structure = "object";
529				file->type = SC_FILE_TYPE_WORKING_EF;
530				file->ef_structure = SC_FILE_EF_TRANSPARENT; /* TODO */
531			} else if (taglen == 3 && tag[1] == 0x21) {
532				type = "working EF";
533				file->record_length = tag[2];
534				file->type = SC_FILE_TYPE_WORKING_EF;
535				/* linear fixed, cyclic or compute */
536				switch ( tag[0] )
537				{
538					case 0x02:
539						structure = "linear fixed";
540						file->ef_structure = SC_FILE_EF_LINEAR_FIXED;
541						break;
542					case 0x07:
543						structure = "cyclic";
544						file->ef_structure = SC_FILE_EF_CYCLIC;
545						break;
546					case 0x17:
547						structure = "compute";
548						file->ef_structure = SC_FILE_EF_UNKNOWN;
549						break;
550					default:
551						structure = "unknown";
552						file->ef_structure = SC_FILE_EF_UNKNOWN;
553						file->record_length = 0;
554						break;
555				}
556			}
557	
558			sc_log(ctx,
559				"  type: %s\n", type);
560			sc_log(ctx,
561				"  EF structure: %s\n", structure);
562		}
563		file->magic = SC_FILE_MAGIC;
564	
565		return SC_SUCCESS;
566	}
567	
568	static int process_fci_v3_4(sc_context_t *ctx, sc_file_t *file,
569			       const u8 *buf, size_t buflen)
570	{
571		size_t taglen, len = buflen;
572		const u8 *tag = NULL, *p;
573	
574		sc_log(ctx,
575			 "processing %"SC_FORMAT_LEN_SIZE_T"u FCI bytes\n", buflen);
576	
577		if (buflen < 2)
578			return SC_ERROR_INTERNAL;
579		if (buf[0] != 0x6f)
580			return SC_ERROR_INVALID_DATA;
581		len = (size_t)buf[1];
582		if (buflen - 2 < len)
583			return SC_ERROR_INVALID_DATA;
584	
585		/* defaults */
586		file->type = SC_FILE_TYPE_WORKING_EF;
587		if (len == 0) {
588			SC_FUNC_RETURN(ctx, 2, SC_SUCCESS);
589		}
590	
591		p = buf + 2;
592		file->ef_structure = SC_FILE_TYPE_DF;
593		file->shareable = 1;
594		tag = sc_asn1_find_tag(ctx, p, len, 0x84, &taglen);
595		if (tag != NULL && taglen > 0 && taglen <= 16) {
596			memcpy(file->name, tag, taglen);
597			file->namelen = taglen;
598			sc_log(ctx,  "filename %s",
599				sc_dump_hex(file->name, file->namelen));
600		}
601		return SC_SUCCESS;
602	}
603	
604	static int process_fcp_v3_4(sc_context_t *ctx, sc_file_t *file,
605			       const u8 *buf, size_t buflen)
606	{
607		size_t taglen, len = buflen;
608		const u8 *tag = NULL, *p;
609	
610		sc_log(ctx,
611			 "processing %"SC_FORMAT_LEN_SIZE_T"u FCP bytes\n", buflen);
612	
613		if (buflen < 2)
614			return SC_ERROR_INTERNAL;
615		if (buf[0] != 0x62)
616			return SC_ERROR_INVALID_DATA;
617		len = (size_t)buf[1];
618		if (buflen - 2 < len)
619			return SC_ERROR_INVALID_DATA;
620		p = buf + 2;
621	
622		tag = sc_asn1_find_tag(ctx, p, len, 0x80, &taglen);
623		if (tag != NULL && taglen >= 2) {
624			int bytes = (tag[0] << 8) + tag[1];
625			sc_log(ctx,
626				"  bytes in file: %d\n", bytes);
627			file->size = bytes;
628		}
629	
630		tag = sc_asn1_find_tag(ctx, p, len, 0xc5, &taglen);
631		if (tag != NULL && taglen >= 2) {
632			int bytes = (tag[0] << 8) + tag[1];
633			sc_log(ctx,
634				"  bytes in file 2: %d\n", bytes);
635			file->size = bytes;
636		}
637	
638		tag = sc_asn1_find_tag(ctx, p, len, 0x82, &taglen);
639		if (tag != NULL) {
640			const char *type = "unknown";
641			const char *structure = "unknown";
642	
643			if (taglen >= 1) {
644				unsigned char byte = tag[0];
645				if (byte & 0x40) {
646					file->shareable = 1;
647				}
648				if (byte == 0x38) {
649					type = "DF";
650					file->type = SC_FILE_TYPE_DF;
651					file->shareable = 1;
652				}
653				switch (byte & 7) {
654				case 1:
655					/* transparent EF */
656					type = "working EF";
657					structure = "transparent";
658					file->type = SC_FILE_TYPE_WORKING_EF;
659					file->ef_structure = SC_FILE_EF_TRANSPARENT;
660					break;
661				case 2:
662					/* linear fixed EF */
663					type = "working EF";
664					structure = "linear fixed";
665					file->type = SC_FILE_TYPE_WORKING_EF;
666					file->ef_structure = SC_FILE_EF_LINEAR_FIXED;
667					break;
668				case 4:
669					/* linear variable EF */
670					type = "working EF";
671					structure = "linear variable";
672					file->type = SC_FILE_TYPE_WORKING_EF;
673					file->ef_structure = SC_FILE_EF_LINEAR_VARIABLE;
674					break;
675				case 6:
676					/* cyclic EF */
677					type = "working EF";
678					structure = "cyclic";
679					file->type = SC_FILE_TYPE_WORKING_EF;
680					file->ef_structure = SC_FILE_EF_CYCLIC;
681					break;
682				default:
683					/* use defaults from above */
684					break;
685				}
686			}
687			sc_log(ctx,
688				"  type: %s\n", type);
689			sc_log(ctx,
690				"  EF structure: %s\n", structure);
691			if (taglen >= 2) {
692				if (tag[1] != 0x41 || taglen != 5) {
693					SC_FUNC_RETURN(ctx, 2,SC_ERROR_INVALID_DATA);
694				}
695				/* formatted EF */
696				file->record_length = (tag[2] << 8) + tag[3];
697				file->record_count = tag[4];
698				sc_log(ctx,
699					"  rec_len: %"SC_FORMAT_LEN_SIZE_T"u  rec_cnt: %"SC_FORMAT_LEN_SIZE_T"u\n\n",
700					file->record_length, file->record_count);
701			}
702		}
703	
704		tag = sc_asn1_find_tag(ctx, p, len, 0x83, &taglen);
705		if (tag != NULL && taglen >= 2) {
706			file->id = (tag[0] << 8) | tag[1];
707			sc_log(ctx,  "  file identifier: 0x%02X%02X\n",
708				tag[0], tag[1]);
709		}
710	
711		tag = sc_asn1_find_tag(ctx, p, len, 0x84, &taglen);
712		if (tag != NULL && taglen > 0 && taglen <= 16) {
713			memcpy(file->name, tag, taglen);
714			file->namelen = taglen;
715			sc_log(ctx,  "  filename %s",
716				sc_dump_hex(file->name, file->namelen));
717		}
718	
719		tag = sc_asn1_find_tag(ctx, p, len, 0x8a, &taglen);
720		if (tag != NULL && taglen == 1) {
721			char* status = "unknown";
722			switch (tag[0]) {
723			case 1:
724				status = "creation";
725				file->status = SC_FILE_STATUS_CREATION;
726				break;
727			case 5:
728				status = "operational active";
729				file->status = SC_FILE_STATUS_ACTIVATED;
730				break;
731			case 12:
732			case 13:
733				status = "creation";
734				file->status = SC_FILE_STATUS_INVALIDATED;
735				break;
736			default:
737				break;
738			}
739			sc_log(ctx,  "  file status: %s\n", status);
740		}
741	
742		file->magic = SC_FILE_MAGIC;
743		return SC_SUCCESS;
744	}
745	
746	static int starcos_select_aid(sc_card_t *card,
747				      const u8 aid[16], size_t len,
748				      sc_file_t **file_out)
749	{
750		sc_apdu_t apdu;
751		int r;
752		size_t i = 0;
753	
754		sc_format_apdu(card, &apdu, SC_APDU_CASE_3_SHORT, 0xA4, 0x04, 0x0C);
755		apdu.lc = len;
756		apdu.data = (u8*)aid;
757		apdu.datalen = len;
758		apdu.resplen = 0;
759		apdu.le = 0;
760		r = sc_transmit_apdu(card, &apdu);
761		LOG_TEST_RET(card->ctx, r, "APDU transmit failed");
762	
763		/* check return value */
764		if (!(apdu.sw1 == 0x90 && apdu.sw2 == 0x00) && apdu.sw1 != 0x61 )
765			SC_FUNC_RETURN(card->ctx, SC_LOG_DEBUG_VERBOSE, sc_check_sw(card, apdu.sw1, apdu.sw2));
766	
767		/* update cache */
768		card->cache.current_path.type = SC_PATH_TYPE_DF_NAME;
769		card->cache.current_path.len = len;
770		memcpy(card->cache.current_path.value, aid, len);
771	
772		if (file_out) {
773			sc_file_t *file = sc_file_new();
774			if (!file)
775				LOG_FUNC_RETURN(card->ctx, SC_ERROR_OUT_OF_MEMORY);
776			file->type = SC_FILE_TYPE_DF;
777			file->ef_structure = SC_FILE_EF_UNKNOWN;
778			file->path.len = 0;
779			file->size = 0;
780			/* AID */
781			for (i = 0; i < len; i++)
782				file->name[i] = aid[i];
783			file->namelen = len;
784			file->id = 0x0000;
785			file->magic = SC_FILE_MAGIC;
786	
787			*file_out = file;
788		}
789		SC_FUNC_RETURN(card->ctx, SC_LOG_DEBUG_VERBOSE, SC_SUCCESS);
790	}
791	
792	static int starcos_select_fid(sc_card_t *card,
793				      unsigned int id_hi, unsigned int id_lo,
794				      sc_file_t **file_out, int is_file)
795	{
796		sc_apdu_t apdu;
797		u8 data[] = {id_hi & 0xff, id_lo & 0xff};
798		u8 resp[SC_MAX_APDU_BUFFER_SIZE];
799		int bIsDF = 0, r;
800		int isFCP = 0;
801		int isMF = 0;
802	
803		/* request FCI to distinguish between EFs and DFs */
804		sc_format_apdu(card, &apdu, SC_APDU_CASE_4_SHORT, 0xA4, 0x00, 0x00);
805		apdu.p2   = 0x00;
806		apdu.resp = (u8*)resp;
807		apdu.resplen = SC_MAX_APDU_BUFFER_SIZE;
808		apdu.le = 256;
809		apdu.lc = 2;
810		apdu.data = (u8*)data;
811		apdu.datalen = 2;
812	
813		if ( IS_V3x(card) ) {
814			if (id_hi == 0x3f && id_lo == 0x0) {
815				apdu.p1 = 0x0;
816				apdu.p2 = 0x0C;
817				apdu.le = 0;
818				apdu.resplen = 0;
819				apdu.resp = NULL;
820				apdu.cse = SC_APDU_CASE_3_SHORT;
821				isMF = 1;
822			} else if (file_out || is_file) {
823				// last component (i.e. file or path)
824				apdu.p1 = 0x2;
825				apdu.p2 = 0x4;
826			} else {
827				// path component
828				apdu.p1 = 0x1;
829				apdu.p2 = 0x0;
830			}
831		}
832	
833		r = sc_transmit_apdu(card, &apdu);
834		LOG_TEST_RET(card->ctx, r, "APDU transmit failed");
835	
836		if (apdu.p2 == 0x00 && apdu.sw1 == 0x62 && apdu.sw2 == 0x84 ) {
837			/* no FCI => we have a DF (see comment in process_fci()) */
838			bIsDF = 1;
839			apdu.p2 = 0x0C;
840			apdu.cse = SC_APDU_CASE_3_SHORT;
841			apdu.resplen = 0;
842			apdu.le = 0;
843			r = sc_transmit_apdu(card, &apdu);
844			LOG_TEST_RET(card->ctx, r, "APDU re-transmit failed");
845		} else if ((IS_V3x(card))
846				&& apdu.p2 == 0x4 && apdu.sw1 == 0x6a && apdu.sw2 == 0x82) {
847			/* not a file, could be a path */
848			bIsDF = 1;
849			apdu.p1 = 0x1;
850			apdu.p2 = 0x0;
851			apdu.resplen = sizeof(resp);
852			apdu.le = 256;
853			apdu.lc = 2;
854			r = sc_transmit_apdu(card, &apdu);
855			LOG_TEST_RET(card->ctx, r, "APDU re-transmit failed");
856		} else if (apdu.sw1 == 0x61 || (apdu.sw1 == 0x90 && apdu.sw2 == 0x00 && !isMF)) {
857			/* SELECT returned some data (possible FCI) =>
858			 * try a READ BINARY to see if a EF is selected */
859			sc_apdu_t apdu2;
860			u8 resp2[2];
861			sc_format_apdu(card, &apdu2, SC_APDU_CASE_2_SHORT, 0xB0, 0, 0);
862			apdu2.resp = (u8*)resp2;
863			apdu2.resplen = 2;
864			apdu2.le = 1;
865			apdu2.lc = 0;
866			r = sc_transmit_apdu(card, &apdu2);
867			LOG_TEST_RET(card->ctx, r, "APDU transmit failed");
868			if (apdu2.sw1 == 0x69 && apdu2.sw2 == 0x86) {
869				/* no current EF is selected => we have a DF */
870				bIsDF = 1;
871			} else {
872				isFCP = 1;
873			}
874		}
875	
876		if (apdu.sw1 != 0x61 && (apdu.sw1 != 0x90 || apdu.sw2 != 0x00))
877			SC_FUNC_RETURN(card->ctx, SC_LOG_DEBUG_VERBOSE, sc_check_sw(card, apdu.sw1, apdu.sw2));
878	
879		/* update cache */
880		if (bIsDF || isMF) {
881			card->cache.current_path.type = SC_PATH_TYPE_PATH;
882			card->cache.current_path.value[0] = 0x3f;
883			card->cache.current_path.value[1] = 0x00;
884			if (id_hi == 0x3f && id_lo == 0x00)
885				card->cache.current_path.len = 2;
886			else {
887				card->cache.current_path.len = 4;
888				card->cache.current_path.value[2] = id_hi;
889				card->cache.current_path.value[3] = id_lo;
890			}
891		}
892	
893		if (file_out) {
894			sc_file_t *file = sc_file_new();
895			if (!file)
896				LOG_FUNC_RETURN(card->ctx, SC_ERROR_OUT_OF_MEMORY);
897			file->id   = (id_hi << 8) + id_lo;
898			file->path = card->cache.current_path;
899	
900			if (bIsDF || isMF) {
901				/* we have a DF */
902				file->type = SC_FILE_TYPE_DF;
903				file->ef_structure = SC_FILE_EF_UNKNOWN;
904				file->size = 0;
905				file->namelen = 0;
906				file->magic = SC_FILE_MAGIC;
907				*file_out = file;
908			} else {
909				/* ok, assume we have a EF */
910				if ( IS_V3x(card) ) {
911					if (isFCP) {
912						r = process_fcp_v3_4(card->ctx, file, apdu.resp,
913								apdu.resplen);
914					} else {
915						r = process_fci_v3_4(card->ctx, file, apdu.resp,
916								apdu.resplen);
917					}
918				} else {
919					r = process_fci(card->ctx, file, apdu.resp,
920							apdu.resplen);
921				}
922				if (r != SC_SUCCESS) {
923					sc_file_free(file);
924					return r;
925				}
926	
927				*file_out = file;
928			}
929		}
930	
931		SC_FUNC_RETURN(card->ctx, SC_LOG_DEBUG_VERBOSE, SC_SUCCESS);
932	}
933	
934	static int starcos_select_file(sc_card_t *card,
935				       const sc_path_t *in_path,
936				       sc_file_t **file_out)
937	{
938		u8 pathbuf[SC_MAX_PATH_SIZE], *path = pathbuf;
939		int    r, pathtype;
940		size_t i, pathlen;
941		char pbuf[SC_MAX_PATH_STRING_SIZE];
942	
943		SC_FUNC_CALLED(card->ctx, SC_LOG_DEBUG_VERBOSE);
944	
945		r = sc_path_print(pbuf, sizeof(pbuf), &card->cache.current_path);
946		if (r != SC_SUCCESS)
947			pbuf[0] = '\0';
948	
949		sc_log(card->ctx,
950			 "current path (%s): %s (len: %"SC_FORMAT_LEN_SIZE_T"u)\n",
951			 card->cache.current_path.type == SC_PATH_TYPE_DF_NAME ?
952			 "aid" : "path", pbuf, card->cache.current_path.len);
953	
954		if ( in_path->len > sizeof(pathbuf) ) {
955			SC_FUNC_RETURN(card->ctx, SC_LOG_DEBUG_VERBOSE, SC_ERROR_BUFFER_TOO_SMALL);
956		}
957		memcpy(path, in_path->value, in_path->len);
958		pathlen = in_path->len;
959		pathtype = in_path->type;
960	
961		if (in_path->aid.len) {
962			if (!pathlen) {
963				if ( in_path->aid.len > sizeof(pathbuf) ) {
964					SC_FUNC_RETURN(card->ctx, SC_LOG_DEBUG_VERBOSE, SC_ERROR_BUFFER_TOO_SMALL);
965				}
966				memcpy(path, in_path->aid.value, in_path->aid.len);
967				pathlen = in_path->aid.len;
968				pathtype = SC_PATH_TYPE_DF_NAME;
969			} else {
970				r = starcos_select_aid(card, in_path->aid.value, in_path->aid.len, NULL);
971				LOG_TEST_RET(card->ctx, r, "Could not select AID!");
972	
973				if (pathtype == SC_PATH_TYPE_DF_NAME) {
974					pathtype = SC_PATH_TYPE_FILE_ID;
975				}
976			}
977		}
978	
979		if (pathtype == SC_PATH_TYPE_FILE_ID)
980		{	/* SELECT EF/DF with ID */
981			/* Select with 2byte File-ID */
982			if (pathlen != 2)
983				SC_FUNC_RETURN(card->ctx, SC_LOG_DEBUG_VERBOSE,SC_ERROR_INVALID_ARGUMENTS);
984			r = starcos_select_fid(card, path[0],
985					path[1], path[0] == 0x3F && path[1] == 0x00 ? NULL : file_out, 1);
986			SC_FUNC_RETURN(card->ctx, SC_LOG_DEBUG_VERBOSE, r);
987		}
988		else if (pathtype == SC_PATH_TYPE_DF_NAME)
989		{	/* SELECT DF with AID */
990			/* Select with 1-16byte Application-ID */
991			r = starcos_select_aid(card, pathbuf, pathlen, file_out);
992			SC_FUNC_RETURN(card->ctx, SC_LOG_DEBUG_VERBOSE, r);
993		}
994		else if (pathtype == SC_PATH_TYPE_PATH)
995		{
996			u8 n_pathbuf[SC_MAX_PATH_SIZE];
997	
998			/* Select with path (sequence of File-IDs) */
999			/* Starcos (S 2.1 and SPK 2.3) only supports one
1000			 * level of subdirectories, therefore a path is
1001			 * at most 3 FID long (the last one being the FID
1002			 * of a EF) => pathlen must be even and less than 6
1003			 */
1004			if (pathlen%2 != 0 || pathlen > 6 || pathlen <= 0)
1005				SC_FUNC_RETURN(card->ctx, SC_LOG_DEBUG_VERBOSE, SC_ERROR_INVALID_ARGUMENTS);
1006			/* if pathlen == 6 then the first FID must be MF (== 3F00) */
1007			if (pathlen == 6 && ( path[0] != 0x3f || path[1] != 0x00 ))
1008				SC_FUNC_RETURN(card->ctx, SC_LOG_DEBUG_VERBOSE, SC_ERROR_INVALID_ARGUMENTS);
1009	
1010			if ( IS_V3x(card) ) {
1011				/* unify path (the first FID should be MF) */
1012				if (path[0] != 0x3f || path[1] != 0x00)
1013				{
1014					n_pathbuf[0] = 0x3f;
1015					n_pathbuf[1] = 0x00;
1016					memcpy(n_pathbuf+2, path, pathlen);
1017					path = n_pathbuf;
1018					pathlen += 2;
1019				}
1020			}
1021	
1022			for ( i=0; i<pathlen-2; i+=2 )
1023			{
1024				r = starcos_select_fid(card, path[i], path[i+1], NULL, 0);
1025				LOG_TEST_RET(card->ctx, r, "SELECT FILE (DF-ID) failed");
1026			}
1027			r = starcos_select_fid(card, path[pathlen-2], path[pathlen-1], file_out, 1);
1028			SC_FUNC_RETURN(card->ctx, SC_LOG_DEBUG_VERBOSE, r);
1029		}
1030		else
1031			SC_FUNC_RETURN(card->ctx, SC_LOG_DEBUG_VERBOSE, SC_ERROR_INVALID_ARGUMENTS);
1032	}
