1044	
1045	#define STARCOS_AC_ALWAYS	0x9f
1046	#define STARCOS_AC_NEVER	0x5f
1047	#define STARCOS_PINID2STATE(a)	((((a) & 0x0f) == 0x01) ? ((a) & 0x0f) : (0x0f - ((0x0f & (a)) >> 1)))
1048	
1049	static u8 process_acl_entry(sc_file_t *in, unsigned int method, unsigned int in_def)
1050	{
1051		u8 def = (u8)in_def;
1052		const sc_acl_entry_t *entry = sc_file_get_acl_entry(in, method);
1053		if (!entry)
1054			return def;
1055		else if (entry->method & SC_AC_CHV) {
1056			unsigned int key_ref = entry->key_ref;
1057			if (key_ref == SC_AC_KEY_REF_NONE)
1058				return def;
1059			else if ((key_ref & 0x0f) == 1)
1060				/* SOPIN */
1061				return (key_ref & 0x80 ? 0x10 : 0x00) | 0x01;
1062			else
1063				return (key_ref & 0x80 ? 0x10 : 0x00) | STARCOS_PINID2STATE(key_ref);
1064		} else if (entry->method & SC_AC_NEVER)
1065			return STARCOS_AC_NEVER;
1066		else
1067			return def;
1068	}
1069	
1070	/** starcos_process_acl
1071	 * \param card pointer to the sc_card object
1072	 * \param file pointer to the sc_file object
1073	 * \param data pointer to a sc_starcos_create_data structure
1074	 * \return SC_SUCCESS if no error occurred otherwise error code
1075	 *
1076	 * This function tries to create a somewhat usable Starcos spk 2.3 acl
1077	 * from the OpenSC internal acl (storing the result in the supplied
1078	 * sc_starcos_create_data structure).
1079	 */
1080	static int starcos_process_acl(sc_card_t *card, sc_file_t *file,
1081		sc_starcos_create_data *data)
1082	{
1083		u8     tmp, *p;
1084		static const u8 def_key[] = {0x01,0x02,0x03,0x04,0x05,0x06,0x07,0x08};
1085	
1086		if (file->type == SC_FILE_TYPE_DF && file->id == 0x3f00) {
1087			p    = data->data.mf.header;
1088			memcpy(p, def_key, 8);
1089			p   += 8;
1090			*p++ = (file->size >> 8) & 0xff;
1091			*p++ = file->size & 0xff;
1092			/* guess isf size (mf_size / 4) */
1093			*p++ = (file->size >> 10) & 0xff;
1094			*p++ = (file->size >> 2)  & 0xff;
1095			/* ac create ef  */
1096			*p++ = process_acl_entry(file,SC_AC_OP_CREATE,STARCOS_AC_ALWAYS);
1097			/* ac create key */
1098			*p++ = process_acl_entry(file,SC_AC_OP_CREATE,STARCOS_AC_ALWAYS);
1099			/* ac create df  */
1100			*p++ = process_acl_entry(file,SC_AC_OP_CREATE,STARCOS_AC_ALWAYS);
1101			/* use the same ac for register df and create df */
1102			*p++ = data->data.mf.header[14];
1103			/* if sm is required use combined mode */
1104			if (file->acl[SC_AC_OP_CREATE] && (sc_file_get_acl_entry(file, SC_AC_OP_CREATE))->method & SC_AC_PRO)
1105				tmp = 0x03;	/* combined mode */
1106			else
1107				tmp = 0x00;	/* no sm */
1108			*p++ = tmp;	/* use the same sm mode for all ops */
1109			*p++ = tmp;
1110			*p = tmp;
1111			data->type = SC_STARCOS_MF_DATA;
1112	
1113			return SC_SUCCESS;
1114		} else if (file->type == SC_FILE_TYPE_DF){
1115			p    = data->data.df.header;
1116			*p++ = (file->id >> 8) & 0xff;
1117			*p++ = file->id & 0xff;
1118			if (file->namelen) {
1119				/* copy aid */
1120				*p++ = file->namelen & 0xff;
1121				memset(p, 0, 16);
1122				memcpy(p, file->name, (u8)file->namelen);
1123				p   += 16;
1124			} else {
1125				/* use the fid as aid */
1126				*p++ = 2;
1127				memset(p, 0, 16);
1128				*p++ = (file->id >> 8) & 0xff;
1129				*p++ = file->id & 0xff;
1130				p   += 14;
1131			}
1132			/* guess isf size */
1133			*p++ = (file->size >> 10) & 0xff;	/* ISF space */
1134			*p++ = (file->size >> 2)  & 0xff;	/* ISF space */
1135			/* ac create ef  */
1136			*p++ = process_acl_entry(file,SC_AC_OP_CREATE,STARCOS_AC_ALWAYS);
1137			/* ac create key */
1138			*p++ = process_acl_entry(file,SC_AC_OP_CREATE,STARCOS_AC_ALWAYS);
1139			/* set sm byte (same for keys and ef) */
1140			if (file->acl[SC_AC_OP_CREATE] &&
1141			    (sc_file_get_acl_entry(file, SC_AC_OP_CREATE)->method &
1142			     SC_AC_PRO))
1143				tmp = 0x03;
1144			else
1145				tmp = 0x00;
1146			*p++ = tmp;	/* SM CR  */
1147			*p = tmp;	/* SM ISF */
1148	
1149			data->data.df.size[0] = (file->size >> 8) & 0xff;
1150			data->data.df.size[1] = file->size & 0xff;
1151			data->type = SC_STARCOS_DF_DATA;
1152	
1153			return SC_SUCCESS;
1154		} else if (file->type == SC_FILE_TYPE_WORKING_EF) {
1155			p    = data->data.ef.header;
1156			*p++ = (file->id >> 8) & 0xff;
1157			*p++ = file->id & 0xff;
1158			/* ac read  */
1159			*p++ = process_acl_entry(file, SC_AC_OP_READ,STARCOS_AC_ALWAYS);
1160			/* ac write */
1161			*p++ = process_acl_entry(file, SC_AC_OP_WRITE,STARCOS_AC_ALWAYS);
1162			/* ac erase */
1163			*p++ = process_acl_entry(file, SC_AC_OP_ERASE,STARCOS_AC_ALWAYS);
1164			*p++ = STARCOS_AC_ALWAYS;	/* AC LOCK     */
1165			*p++ = STARCOS_AC_ALWAYS;	/* AC UNLOCK   */
1166			*p++ = STARCOS_AC_ALWAYS;	/* AC INCREASE */
1167			*p++ = STARCOS_AC_ALWAYS;	/* AC DECREASE */
1168			*p++ = 0x00;			/* rfu         */
1169			*p++ = 0x00;			/* rfu         */
1170			/* use sm (in combined mode) if wanted */
1171			if ((file->acl[SC_AC_OP_READ]   && (sc_file_get_acl_entry(file, SC_AC_OP_READ)->method & SC_AC_PRO)) ||
1172			    (file->acl[SC_AC_OP_UPDATE] && (sc_file_get_acl_entry(file, SC_AC_OP_UPDATE)->method & SC_AC_PRO)) ||
1173			    (file->acl[SC_AC_OP_WRITE]  && (sc_file_get_acl_entry(file, SC_AC_OP_WRITE)->method & SC_AC_PRO)) )
1174				tmp = 0x03;
1175			else
1176				tmp = 0x00;
1177			*p++ = tmp;			/* SM byte     */
1178			*p++ = 0x00;			/* use the least significant 5 bits
1179						 	 * of the FID as SID */
1180			switch (file->ef_structure)
1181			{
1182			case SC_FILE_EF_TRANSPARENT:
1183				*p++ = 0x81;
1184				*p++ = (file->size >> 8) & 0xff;
1185				*p = file->size & 0xff;
1186				break;
1187			case SC_FILE_EF_LINEAR_FIXED:
1188				*p++ = 0x82;
1189				*p++ = file->record_count  & 0xff;
1190				*p = file->record_length & 0xff;
1191				break;
1192			case SC_FILE_EF_CYCLIC:
1193				*p++ = 0x84;
1194				*p++ = file->record_count  & 0xff;
1195				*p = file->record_length & 0xff;
1196				break;
1197			default:
1198				return SC_ERROR_INVALID_ARGUMENTS;
1199			}
1200			data->type = SC_STARCOS_EF_DATA;
1201	
1202			return SC_SUCCESS;
1203		} else
1204	                return SC_ERROR_INVALID_ARGUMENTS;
1205	}
