336	/* returns 1 if the card has the eSign app with AID A0:00:00:02:45:53:69:67:6E
337	   otherwise returns 0
338	 */
339	static int starcos_has_esign_app(sc_card_t * card) {
340		static const char * starcos_esign_aid = "A0:00:00:02:45:53:69:67:6E";
341		int rv;
342	
343		rv = starcos_select_mf(card);
344		if ( rv == SC_SUCCESS ) {
345			u8 aid[SC_MAX_PATH_SIZE];
346			size_t len = sizeof(aid);
347	
348			rv = sc_hex_to_bin(starcos_esign_aid, aid, &len);
349			LOG_TEST_RET(card->ctx, rv, "Failed to convert eSing AID");
350			rv = starcos_select_aid(card, aid, len, NULL);
351			if ( rv == SC_SUCCESS ) {
352				starcos_select_mf(card);
353			}
354		}
355		return ( rv == SC_SUCCESS );
356	}
