1346	/** starcos_create_file
1347	 * \param card pointer to the sc_card structure
1348	 * \param file pointer to a sc_file object
1349	 * \return SC_SUCCESS or error code
1350	 *
1351	 * This function creates MF, DF or EF based on the supplied
1352	 * information in the sc_file structure (using starcos_process_acl).
1353	 */
1354	static int starcos_create_file(sc_card_t *card, sc_file_t *file)
1355	{
1356		int    r;
1357		sc_starcos_create_data data;
1358	
1359		CHECK_NOT_SUPPORTED_V3_4(card);
1360	
1361		SC_FUNC_CALLED(card->ctx, SC_LOG_DEBUG_VERBOSE);
1362	
1363		if (file->type == SC_FILE_TYPE_DF) {
1364			if (file->id == 0x3f00) {
1365				/* CREATE MF */
1366				r = starcos_process_acl(card, file, &data);
1367				if (r != SC_SUCCESS)
1368					return r;
1369				return starcos_create_mf(card, &data);
1370			} else {
1371				/* CREATE DF */
1372				r = starcos_process_acl(card, file, &data);
1373				if (r != SC_SUCCESS)
1374					return r;
1375				return starcos_create_df(card, &data);
1376			}
1377		} else if (file->type == SC_FILE_TYPE_WORKING_EF) {
1378			/* CREATE EF */
1379			r = starcos_process_acl(card, file, &data);
1380			if (r != SC_SUCCESS)
1381				return r;
1382			return starcos_create_ef(card, &data);
1383		} else
1384			return SC_ERROR_INVALID_ARGUMENTS;
1385	}
