16	 * Foundation, Inc., 51 Franklin Street, Fifth Floor, Boston, MA 02110-1301 USA
17	 */
18	
19	#include "fuzzer_reader.h"
20	
21	/* private data structures */
22	struct driver_data {
23	    const uint8_t *Data;
24	    size_t Size;
25	};
26	
27	static struct sc_reader_operations fuzz_ops = {0};
28	static struct sc_reader_driver fuzz_drv = {
29	    "Fuzzing reader",
30	    "fuzz",
31	    &fuzz_ops,
32	    NULL
33	};
34	
35	void fuzz_get_chunk(sc_reader_t *reader, const uint8_t **chunk, uint16_t *chunk_size)
36	{
37	    struct driver_data *data;
38	    uint16_t c_size;
39	    const uint8_t *c;
40	
41	    if (chunk)
42	        *chunk = NULL;
43	    if (chunk_size)
44	        *chunk_size = 0;
45	
46	    if (!chunk || !chunk_size || !reader) {
47	        if (reader)
48	            sc_debug(reader->ctx, SC_LOG_DEBUG_VERBOSE_TOOL, "Invalid Arguments");
49	        return;
50	    }
51	    data = reader->drv_data;
52	    if (!data || !data->Data || data->Size < sizeof c_size) {
53	        sc_debug(reader->ctx, SC_LOG_DEBUG_VERBOSE_TOOL, "Invalid Arguments");
54	        return;
55	    }
56	    /* parse the length of the returned data on two bytes */
57	    c_size = *((uint16_t *) data->Data);
58	    /* consume two bytes from the fuzzing data */
59	    data->Size -= sizeof c_size;
60	    data->Data += sizeof c_size;
61	
62	    if (data->Size < c_size) {
63	        c_size = data->Size;
64	    }
65	
66	    /* consume the bytes from the fuzzing data */
67	    c = data->Data;
68	    data->Size -= c_size;
69	    data->Data += c_size;
70	
71	    sc_debug_hex(reader->ctx, SC_LOG_DEBUG_VERBOSE_TOOL,
72	        "Returning fuzzing chunk", c, c_size);
73	
74	    *chunk = c;
75	    *chunk_size = c_size;
76	}
77	
78	static int fuzz_reader_release(sc_reader_t *reader)
79	{
80	    if (reader) {
81	        free(reader->drv_data);
82	        reader->drv_data = NULL;
83	    }
84	
85	    return SC_SUCCESS;
86	}
87	
88	static int fuzz_reader_connect(sc_reader_t *reader)
89	{
90	    uint16_t chunk_size;
91	    const uint8_t *chunk;
92	
93	    fuzz_get_chunk(reader, &chunk, &chunk_size);
94	
95	    if (chunk_size > SC_MAX_ATR_SIZE)
96	        chunk_size = SC_MAX_ATR_SIZE;
97	    else
98	        reader->atr.len = chunk_size;
99	
100	    if (chunk_size > 0)
101	        memcpy(reader->atr.value, chunk, chunk_size);
102	
103	    return SC_SUCCESS;
104	}
105	
106	static int fuzz_reader_disconnect(sc_reader_t *reader)
107	{
108	    return SC_SUCCESS;
109	}
110	
111	static int fuzz_reader_transmit(sc_reader_t *reader, sc_apdu_t *apdu)
112	{
113	    const uint8_t *chunk;
114	    uint16_t chunk_size;
115	
116	    fuzz_get_chunk(reader, &chunk, &chunk_size);
117	
118	    if (chunk_size >= 2) {
119	        /* set the SW1 and SW2 status bytes (the last two bytes of
120	         * the response */
121	        apdu->sw1 = (unsigned int)chunk[chunk_size - 2];
122	        apdu->sw2 = (unsigned int)chunk[chunk_size - 1];
123	        chunk_size -= 2;
124	        /* set output length and copy the returned data if necessary */
125	        if (chunk_size <= apdu->resplen)
126	            apdu->resplen = chunk_size;
127	
128	        if (apdu->resplen != 0)
129	            memcpy(apdu->resp, chunk, apdu->resplen);
130	    } else {
131	        apdu->sw1 = 0x6D;
132	        apdu->sw2 = 0x00;
133	        apdu->resplen = 0;
134	    }
135	
136	    return SC_SUCCESS;
137	}
138	
139	static int fuzz_reader_lock(sc_reader_t *reader)
140	{
141	    return 0;
142	}
143	
144	static int fuzz_reader_unlock(sc_reader_t *reader)
145	{
146	    return 0;
147	}
148	
149	struct sc_reader_driver *sc_get_fuzz_driver(void)
150	{
151	    fuzz_ops.release = fuzz_reader_release;
152	    fuzz_ops.connect = fuzz_reader_connect;
153	    fuzz_ops.disconnect = fuzz_reader_disconnect;
154	    fuzz_ops.transmit = fuzz_reader_transmit;
155	    fuzz_ops.lock = fuzz_reader_lock;
156	    fuzz_ops.unlock = fuzz_reader_unlock;
157	    return &fuzz_drv;
158	}
159	
160	void fuzz_add_reader(struct sc_context *ctx, const uint8_t *Data, size_t Size)
161	{
162	    sc_reader_t	*reader;
163	    struct driver_data *data;
164	    char name[64] = {0};
165	
166	    if (!(reader = calloc(1, sizeof(*reader)))
167	            || !(data = (calloc(1, sizeof(*data))))) {
168	        free(reader);
169	        return;
170	    }
171	
172	    data->Data = Data;
173	    data->Size = Size;
174	
175	    reader->driver = &fuzz_drv;
176	    reader->ops = &fuzz_ops;
177	    reader->drv_data = data;
178	    snprintf(name, sizeof name - 1, "%zu random byte%s reader (%p)",
179	            Size, Size == 1 ? "" : "s", Data);
180	    reader->name = strdup(name);
181	
182	    reader->ctx = ctx;
183	    list_append(&ctx->readers, reader);
184	}
185	
186	int fuzz_connect_card(sc_context_t *ctx, sc_card_t **card, sc_reader_t **reader_out,
187	                      const uint8_t *data, size_t size)
188	{
189	    struct sc_reader *reader = NULL;
190	
191	    /* Erase possible readers from ctx */
192	    while (list_size(&ctx->readers)) {
193	        sc_reader_t *rdr = (sc_reader_t *) list_get_at(&ctx->readers, 0);
194	        _sc_delete_reader(ctx, rdr);
195	    }
196	    if (ctx->reader_driver->ops->finish != NULL)
197	        ctx->reader_driver->ops->finish(ctx);
198	
199	    /* Create virtual reader */
200	    ctx->reader_driver = sc_get_fuzz_driver();
201	    fuzz_add_reader(ctx, data, size);
202	    reader = sc_ctx_get_reader(ctx, 0);
203	
204	    /* Connect card */
205	    if (sc_connect_card(reader, card))
206	        return SC_ERROR_INTERNAL;
207	
208	    if (reader_out)
209	        *reader_out = reader;
210	
211	    return SC_SUCCESS;
