1	#
2	# pkcs15 profile for starcos spk 2.3
3	#
4	cardinfo {
5		max-pin-length	= 8;
6		pin-encoding	= ascii-numeric;
7		pin-pad-char	= 0x00;
8	}
9	
10	option default {
11		macros {
12			so-pin-flags	= initialized, needs-padding, soPin;
13			isf_acl		= WRITE=$SOPIN, CREATE=$SOPIN;
14			df_acl		= *=$SOPIN;
15		}
16	}
17	
18	option onepin {
19		macros {
20			so-pin-flags    = initialized, needs-padding;
21			isf_acl		= WRITE=$PIN, CREATE=$PIN;
22			df_acl		= *=$PIN;
23		}
24	}
25	
26	PIN so-pin {
27		reference	= 1;
28		flags		= $so-pin-flags;
29	}
30	PIN so-puk {
31		reference	= 1;
32	}
33	PIN user-pin {
34		attempts	= 3;
35	}
36	PIN user-puk {
37		attempts	= 10;
38	}
39	
40	# Additional filesystem info.
41	# This is added to the file system info specified in the
42	# main profile.
43	filesystem {
44	    DF MF {
45		ACL	= $df_acl;
46		size	= 768;
47	
48		# INTERNAL SECRET KEY file of the MF
49		EF mf_isf {
50			size	= 256;
51			ACL	= $isf_acl;
52		}
53	
54		EF mf_ipf {
55			file-id = 0010;
56			size    = 256;
57		}
58	
59	        DF PKCS15-AppDF {
60			ACL	= $df_acl;
61			size	= 16000;
