66			# 'pkcs15-init --finalize' (in this case the
67			# AC WRITE is NEVER as the required state can't
68			# be reached).
69			EF p15_isf {
70				path		= 3f005015;
71				size		= 2560;
72				ACL		= $isf_acl;
73			}
74	
75			EF p15_ipf {
76				file-id		= 0010;
77				size		= 1280;
78			}
79		
80	
81	            template key-domain {
82			BSO private-key {
83				# here ACLs should be defined
84			}
85	                EF public-key {
86	    	            file-id	= 3003;
87	    	            structure	= transparent;
88			    ACL		= *=NEVER,
