668		if (r != SC_SUCCESS)
669			/* unable to select ipf */
670			return r;
671		len = tfile->size;
672		sc_file_free(tfile);
673		buf = malloc(len);
674		if (!buf)
675			return SC_ERROR_OUT_OF_MEMORY;
676		/* read the complete IPF */
677		r = sc_read_binary(card, 0, buf, len, 0);
678		if (r < 0 || r != (int)len) {
679			free(buf);
680			return r;
681		}
682		/* get/fix number of keys */
683		num_keys = buf[0];
684		if (num_keys == 0xff)
685			num_keys = 0;
686		/* encode public key */
687		keylen  = starcos_encode_pukey(rsa, NULL, kinfo);
688		if (!keylen) {
689			free(buf);
690			return SC_ERROR_INTERNAL;
691		}
692		p = key;
693		*p++ = (u8) kinfo->key_reference;
694		*p++ = (keylen >> 8) & 0xff;
695		*p++ = keylen & 0xff;
696		*p++ = STARCOS_AC_ALWAYS;	/* AC WRITE etc XXX */
697		*p++ = 0x0f;
698		*p++ = 0;
699		*p++ = 0x09;			/* ALGO XXX */
700		*p++ = 0x4a;			/* AKD  XXX */
701		*p++ = ((keylen >> 8) & 0xff) | 0x80;
702		*p++ = keylen & 0xff;
703		r = starcos_encode_pukey(rsa, p, kinfo);
704		if (r != SC_SUCCESS) {
705			free(buf);
706			return SC_ERROR_INTERNAL;
707		}
708		p   += keylen;
709		*p++ = 0x04;				/* CPI */
710		*p = (u8) kinfo->key_reference;	/* CHA */
711		/* updated IPF (XXX: currently append only) */
712		num_keys++;
713		r = sc_update_binary(card, 0, &num_keys, 1, 0);
714		if (r < 0) {
715			free(buf);
716			return r;
717		}
718		endpos = starcos_ipf_get_lastpos(buf, len);
719		free(buf);
720		return sc_update_binary(card, (unsigned)endpos, key, keylen + 12, 0);
721	}
