723	static int starcos_create_key(sc_profile_t *profile, sc_pkcs15_card_t *p15card,
724		sc_pkcs15_object_t *obj)
725	{
726		struct sc_card *card = p15card->card;
727		int	r, pin_id;
728		u8	akd = 0, state;
729	
730		sc_file_t              *tfile;
731		const sc_acl_entry_t   *acl_entry;
732		sc_pkcs15_prkey_info_t *kinfo = (sc_pkcs15_prkey_info_t *)obj->data;
733		sc_starcos_wkey_data    tkey;
734	
735		/* get and verify sopin if necessary */
736		r = sc_profile_get_file(profile, "p15_isf", &tfile);
737	        if (r < 0)
738	                return r;
739		acl_entry = sc_file_get_acl_entry(tfile, SC_AC_OP_WRITE);
740		if (acl_entry->method  != SC_AC_NONE) {
741			r = sc_pkcs15init_authenticate(profile, p15card, tfile, SC_AC_OP_WRITE);
742		}
743		else   {
744			r = sc_select_file(card, &tfile->path, NULL);
745		}
746		sc_file_free(tfile);
747		if (r < 0)
748			return r;
