import struct
import sys

def write_chunk(f, data):
    """Write a chunk: 2-byte little-endian size, then data bytes"""
    f.write(struct.pack('<H', len(data)))
    f.write(data)

def write_apdu_response(f, data, sw1=0x90, sw2=0x00):
    """Write an APDU response chunk with data + SW"""
    chunk = bytes(data) + bytes([sw1, sw2])
    write_chunk(f, chunk)

