}
PIN user-pin {
    attempts = 3;
}
PIN user-puk {
    attempts = 10;
}
filesystem {
    DF MF {
        ACL = $df_acl;
        size = 768;
        EF mf_isf {
            size = 256;
            ACL = $isf_acl;
        }
        EF mf_ipf {
